{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://fsight.local/schemas/project-health/v0.1.0.json",
  "title": "Project Health Report",
  "description": "JSON-представление отчёта о здоровье проекта. Версия схемы 0.1.0 (2026-08-21).",
  "version": "0.1.0",
  "type": "object",
  "required": ["_meta", "summary", "sections"],
  "properties": {
    "_meta": {
      "type": "object",
      "description": "Метаданные: кто создал, когда, по какой версии схемы",
      "required": ["schema_version", "generated_at", "generator", "generator_version", "project_code", "project_id"],
      "properties": {
        "schema_version": {
          "type": "string",
          "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
          "description": "Версия схемы данных (semver). Используется для выбора парсера."
        },
        "generated_at": {
          "type": "string",
          "format": "date-time",
          "description": "ISO-8601 дата-время генерации JSON"
        },
        "generator": {
          "type": "string",
          "const": "fst-project-health",
          "description": "Имя генератора"
        },
        "generator_version": {
          "type": "string",
          "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
          "description": "Версия генератора (скилла)"
        },
        "project_code": {
          "type": "string",
          "pattern": "^[0-9]{3}-[0-9]{3}$",
          "description": "Код проекта в формате NNN-NNN (например, 504-314)"
        },
        "project_id": {
          "type": "integer",
          "minimum": 1,
          "description": "Внутренний ProjectId из MyProject/AllProject"
        },
        "source_md_hash": {
          "type": "string",
          "description": "SHA256 хэш исходного MD-файла (для traceability)"
        }
      }
    },
    "summary": {
      "type": "object",
      "description": "Общая сводка по проекту",
      "required": ["verdict", "verdict_status", "section_verdicts"],
      "properties": {
        "verdict": {
          "type": "string",
          "enum": ["Болен", "Требует внимания", "Здоров"],
          "description": "Общий вердикт проекта"
        },
        "verdict_status": {
          "type": "string",
          "enum": ["sick", "attention", "healthy"],
          "description": "Маппинг вердикта на CSS-класс"
        },
        "indicator_text": {
          "type": "string",
          "description": "Текст на индикаторе (например, 'Проект болен')"
        },
        "section_verdicts": {
          "type": "object",
          "required": ["s3", "s4", "s5", "s6"],
          "properties": {
            "s3": {
              "type": "object",
              "required": ["verdict"],
              "properties": {
                "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
                "critical": {"type": "integer", "minimum": 0},
                "warning": {"type": "integer", "minimum": 0},
                "info": {"type": "integer", "minimum": 0}
              }
            },
            "s4": {
              "type": "object",
              "required": ["verdict"],
              "properties": {
                "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
                "critical": {"type": "integer", "minimum": 0},
                "warning": {"type": "integer", "minimum": 0},
                "info": {"type": "integer", "minimum": 0}
              }
            },
            "s5": {
              "type": "object",
              "required": ["verdict"],
              "properties": {
                "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
                "critical": {"type": "integer", "minimum": 0},
                "warning": {"type": "integer", "minimum": 0},
                "info": {"type": "integer", "minimum": 0}
              }
            },
            "s6": {
              "type": "object",
              "required": ["verdict"],
              "properties": {
                "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
                "critical": {"type": "integer", "minimum": 0},
                "warning": {"type": "integer", "minimum": 0},
                "info": {"type": "integer", "minimum": 0}
              }
            }
          }
        },
        "total_counts": {
          "type": "object",
          "description": "Сумма по всем разделам",
          "properties": {
            "critical": {"type": "integer", "minimum": 0},
            "warning": {"type": "integer", "minimum": 0},
            "info": {"type": "integer", "minimum": 0}
          }
        }
      }
    },
    "sections": {
      "type": "object",
      "description": "Детальные данные разделов 3-8",
      "required": ["s3", "s4", "s5", "s6", "s7", "s8"],
      "properties": {
        "s3": {"$ref": "#/$defs/section_remarks"},
        "s4": {"$ref": "#/$defs/section_completeness"},
        "s5": {"$ref": "#/$defs/section_forecast"},
        "s6": {"$ref": "#/$defs/section_finance"},
        "s7": {"$ref": "#/$defs/section_technical"},
        "s8": {"$ref": "#/$defs/section_indicator"}
      }
    },
    "metadata": {
      "type": "object",
      "description": "Технические метаданные (раздел 7 + информация о среде)",
      "properties": {
        "user": {"type": "string", "description": "Пользователь (если известен)"},
        "metamodel_title": {"type": "string"},
        "metamodel_core_version": {"type": "string"},
        "mcp_url": {"type": "string", "format": "uri"},
        "mcp_version": {"type": "string"}
      }
    },
    "_raw": {
      "type": "object",
      "description": "Сырые данные из MCP (для аудита и трассировки). Может отсутствовать в ранних версиях.",
      "properties": {
        "myproject_row": {"type": "object"},
        "project_entity": {"type": "object"},
        "all_my_point_count": {"type": "integer", "description": "Сколько КТ пришло с сервера (после фильтра ?ProjectId=)"},
        "project_health_cost_my_count": {"type": "integer"},
        "project_resource_plan_count": {"type": "integer"}
      }
    },
    "_legacy": {
      "type": "object",
      "description": "Поля из старых версий схемы, которые больше не используются, но сохраняются для совместимости",
      "additionalProperties": true
    }
  },
  "$defs": {
    "section_remarks": {
      "type": "object",
      "description": "Раздел 3: замечания по срокам КТ",
      "required": ["verdict", "counts", "remarks"],
      "properties": {
        "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
