              "name": {"type": "string"},
              "plan": {"type": "string", "format": "date", "description": "PlanDate"},
              "forecast": {"type": "string", "format": "date", "description": "ForecastDate"},
              "fact": {"type": ["string", "null"], "format": "date"},
              "owner": {"type": "string"},
              "status": {"type": "string", "enum": ["Критическое", "Существенное", "Информационное"]},
              "color": {"type": "string", "enum": ["Красный", "Желтый", "Синий"]}
            }
          }
        }
      }
    },
    "section_completeness": {
      "type": "object",
      "description": "Раздел 4: полнота заполнения проекта",
      "required": ["verdict", "indicators"],
      "properties": {
        "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
        "indicators": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "result"],
            "properties": {
              "name": {"type": "string", "description": "Название показателя"},
              "result": {"type": "string", "enum": ["Да", "Нет", "Неопределено"]},
              "detail": {"type": "string"},
              "status": {"type": "string", "enum": ["Норма", "Существенное", "Информационное"]}
            }
          }
        },
        "effort": {
          "type": "object",
          "description": "Трудозатраты (показатель 4)",
          "properties": {
            "plan_hours": {"type": "number"},
            "forecast_hours": {"type": "number"},
            "fact_hours": {"type": "number"}
          }
        },
        "budget": {
          "type": "object",
          "description": "Финансы (показатель 5)",
          "properties": {
            "act_sum": {"type": "number"},
            "pay_sum": {"type": "number"},
            "delta": {"type": "number"},
            "contract_count": {"type": "integer", "minimum": 0}
          }
        }
      }
    },
    "section_forecast": {
      "type": "object",
      "description": "Раздел 5: актуальность прогнозов",
      "required": ["verdict", "counts", "overdue"],
      "properties": {
        "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
        "counts": {
          "type": "object",
          "properties": {
            "critical": {"type": "integer", "minimum": 0},
            "warning": {"type": "integer", "minimum": 0},
            "info": {"type": "integer", "minimum": 0}
          }
        },
        "overdue": {
          "type": "array",
          "description": "КТ с просроченной прогнозной датой (forecast < today и fact IS NULL)",
          "items": {
            "type": "object",
            "required": ["code", "name", "forecast", "overdue_days", "status"],
            "properties": {
              "code": {"type": "string"},
              "name": {"type": "string"},
              "plan": {"type": "string", "format": "date"},
              "forecast": {"type": "string", "format": "date", "description": "ForecastDate — дата, относительно которой считается просрочка"},
              "overdue_days": {"type": "integer", "minimum": 1, "description": "today - forecast_date в днях"},
              "status": {"type": "string", "enum": ["Критическое", "Существенное", "Информационное"]},
              "color": {"type": "string", "enum": ["Красный", "Желтый", "Синий"]},
              "owner": {"type": "string"}
            }
          }
        }
      }
    },
    "section_finance": {
      "type": "object",
      "description": "Раздел 6: финансовый статус (3 показателя)",
      "required": ["verdict", "indicators"],
      "properties": {
        "verdict": {"type": "string", "enum": ["Болен", "Требует внимания", "Здоров"]},
        "indicators": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "result", "detail"],
            "properties": {
              "name": {"type": "string"},
