            }
          }
        },
        "raw": {
          "type": "object",
          "description": "Сырые числа из ProjectHealthCostMy (для аудита)",
          "properties": {
            "plan": {"type": "number"},
            "forecast": {"type": "number"},
            "fact": {"type": "number"},
            "deviation": {"type": "number"},
            "devcost": {"type": "number"}
          }
        }
      }
    },
    "section_technical": {
      "type": "object",
