## Пример полного JSON

См. `examples/v0.1.0_504-314.json`.

"""
generate_json.py — генерирует JSON v0.1.0 из /tmp/project_<code>_report.md.

Использование:
    python3 generate_json.py --code 504-314
    python3 generate_json.py --md /tmp/project_504-314_report.md --output /tmp/foo.json

Парсит:
- _meta (project_code, project_id, generator_version, generated_at)
- summary (verdict из раздела 8)
- sections.s3..s7 (из таблиц в MD)
- sections.s8 (из сводного индикатора)
- metadata (URL MCP из строки "**MCP:**")

Что НЕ парсит (требует отдельной логики):
- effort/budget (из /tmp/proj_<code>.json)
- _raw (из MCP напрямую — нужен сид)
"""
import sys
import json
import re
import argparse
import hashlib
from pathlib import Path
from datetime import datetime, timezone

SCHEMA_VERSION = "0.1.0"
GENERATOR = "fst-project-health"
GENERATOR_VERSION = "0.9.0"


def parse_meta(md_text: str, code: str) -> dict:
    """Парсит метаданные из заголовка MD."""
    # Извлекаем project_id из **Target:** 504-314 (ProjectId=4314)
    m = re.search(r'\*\*Target:\*\*\s+([\d-]+)\s+\(ProjectId=(\d+)\)', md_text)
    if not m:
        raise ValueError(f"Не найден Target в MD: {code}")
    project_id = int(m.group(2))
    return {
        "schema_version": SCHEMA_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generator": GENERATOR,
        "generator_version": GENERATOR_VERSION,
        "project_code": code,
        "project_id": project_id,
        "source_md_hash": hashlib.sha256(md_text.encode()).hexdigest()[:16],
    }


def parse_section(md_text: str, section_num: int) -> str:
    """Извлекает текст раздела N из MD."""
    m = re.search(
        rf'## {section_num}\..*?(?=\n## |\Z)',
        md_text,
        re.DOTALL,
    )
    return m.group(0) if m else ""


def parse_verdict(section_text: str) -> tuple[str, dict]:
    """Извлекает вердикт и counts из раздела."""
    verdict = "Здоров"
    m = re.search(r'\*\*Вердикт раздела:\*\*\s*(.+)', section_text)
    if m:
        verdict = m.group(1).strip()
    counts = {"critical": 0, "warning": 0, "info": 0}
    m = re.search(r'\*\*Критических:\*\*\s*(\d+),\s*\*\*существенных:\*\*\s*(\d+),\s*\*\*информационных:\*\*\s*(\d+)', section_text)
    if m:
        counts["critical"] = int(m.group(1))
        counts["warning"] = int(m.group(2))
        counts["info"] = int(m.group(3))
    return verdict, counts


def parse_md_table(section_text: str) -> list[list[str]]:
    """Простой парсер MD-таблицы. Возвращает rows (без header)."""
    lines = section_text.splitlines()
    in_table = False
    rows = []
    for line in lines:
        if line.startswith("|") and not in_table:
            in_table = True
            # первый row = header — пропускаем
            continue
        if in_table:
            if line.startswith("|"):
                # separator |---|---|...| --- пропускаем
                if re.match(r'^\|[\s\-:|]+\|$', line):
                    continue
                # parse cells
                cells = [c.strip() for c in line.strip("|").split("|")]
                rows.append(cells)
            else:
                # table ended
                if rows:
                    break
    return rows


def parse_s3(md_text: str) -> dict:
    """Раздел 3: замечания по срокам."""
    sec = parse_section(md_text, 3)
    verdict, counts = parse_verdict(sec)
    rows = parse_md_table(sec)
    remarks = []
    for row in rows:
        if len(row) < 8:
            continue
        # MD: [#, Цвет, Статус, Код, Наименование, План, Прогноз, Факт, Исполнитель]
        try:
            remarks.append({
                "code": row[3],
                "name": row[4],
                "plan": row[5] if row[5] != "—" else None,
                "forecast": row[6] if row[6] != "—" else None,
                "fact": row[7] if row[7] != "—" else None,
                "owner": row[8] if len(row) > 8 else "",
                "status": row[2],
                "color": row[1],
            })
        except IndexError:
            continue
    return {"verdict": verdict, "counts": counts, "remarks": remarks}


def parse_s4(md_text: str) -> dict:
    """Раздел 4: полнота заполнения."""
    sec = parse_section(md_text, 4)
    verdict, counts = parse_verdict(sec)
    rows = parse_md_table(sec)
    indicators = []
    for row in rows:
        if len(row) < 4:
            continue
        # MD: [#, Показатель, Результат, Детализация, Статус]
        try:
            indicators.append({
                "name": row[1],
                "result": row[2],
                "detail": row[3],
                "status": row[4] if len(row) > 4 else "Норма",
            })
        except IndexError:
            continue
    return {"verdict": verdict, "indicators": indicators}


def parse_s5(md_text: str) -> dict:
    """Раздел 5: актуальность прогнозов."""
    sec = parse_section(md_text, 5)
    verdict, counts = parse_verdict(sec)
    rows = parse_md_table(sec)
    overdue = []
    for row in rows:
        if len(row) < 7:
            continue
        # MD: [#, Цвет, Статус, Код КТ, Название, План, Прогноз, Дней]
        try:
            overdue.append({
                "code": row[3],
                "name": row[4],
                "plan": row[5] if row[5] != "—" else None,
                "forecast": row[6] if row[6] != "—" else None,
                "overdue_days": int(row[7]) if row[7].isdigit() else None,
                "status": row[2],
                "color": row[1],
            })
        except (IndexError, ValueError):
            continue
    return {"verdict": verdict, "counts": counts, "overdue": overdue}


def parse_s6(md_text: str) -> dict:
    """Раздел 6: финансовый статус."""
    sec = parse_section(md_text, 6)
    verdict, counts = parse_verdict(sec)
    rows = parse_md_table(sec)
    indicators = []
    for row in rows:
        if len(row) < 3:
            continue
        # MD: [#, Показатель, Результат, Детализация]
        try:
            indicators.append({
                "name": row[1],
                "result": row[2],
                "detail": row[3] if len(row) > 3 else "",
            })
        except IndexError:
            continue
    return {"verdict": verdict, "indicators": indicators}


def parse_s7(md_text: str) -> dict:
    """Раздел 7: технические данные."""
    sec = parse_section(md_text, 7)
    rows = parse_md_table(sec)
    result_rows = []
    for row in rows:
        if len(row) < 3:
            continue
        try:
            result_rows.append({
                "name": row[1],
                "value": row[2],
            })
        except IndexError:
            continue
    return {"rows": result_rows}


def parse_s8(md_text: str) -> dict:
    """Раздел 8: индикатор (сводный)."""
    sec = parse_section(md_text, 8)
    status = "Здоров"
    m = re.search(r'\*\*Статус:\s+(\S+)\*\*', sec)
    if m:
        status = m.group(1)
    rows = parse_md_table(sec)
    table = []
    for row in rows:
        if len(row) < 4:
            continue
        try:
            table.append({
                "section": row[0],
                "name": row[1],
                "status": row[2],
                "critical_count": int(re.search(r'\((\d+) крит', row[2]).group(1)) if "крит" in row[2] else 0,
            })
        except (IndexError, AttributeError, ValueError):
            continue
    return {"status": status, "table": table}


def parse_metadata(md_text: str) -> dict:
    """Извлекает метаданные из заголовка и раздела 7."""
    result = {}
    # Из заголовка: **MCP:** PMForesight MCP v3.2.4
    m = re.search(r'\*\*MCP:\*\*\s+(.+)', md_text)
    if m:
        result["mcp_version"] = m.group(1).strip()
    # Из раздела 7 — URL
    m = re.search(r'\|\s*4\s*\|\s*URL MCP-сервера\s*\|\s*([^|]+)\s*\|', md_text)
    if m:
        result["mcp_url"] = m.group(1).strip()
    # Титул и Core version — из раздела 7
    m = re.search(r'\|\s*2\s*\|\s*Титул системы\s*\|\s*([^|]+)\s*\|', md_text)
    if m:
        result["metamodel_title"] = m.group(1).strip()
    m = re.search(r'\|\s*3\s*\|\s*Версия Core\s*\|\s*([^|]+)\s*\|', md_text)
    if m:
        result["metamodel_core_version"] = m.group(1).strip()
    return result


def compute_summary_verdict(section_verdicts: dict) -> tuple[str, str, str]:
    """Общий verdict — самый плохой из разделов 3-6."""
    priority = {"Болен": 3, "Требует внимания": 2, "Здоров": 1}
    worst = "Здоров"
    worst_priority = 1
    for sec in ("s3", "s4", "s5", "s6"):
        v = section_verdicts.get(sec, {}).get("verdict", "Здоров")
        if priority.get(v, 1) > worst_priority:
            worst = v
            worst_priority = priority[v]
    status_map = {"Болен": "sick", "Требует внимания": "attention", "Здоров": "healthy"}
    indicator = {"Болен": "Проект болен", "Требует внимания": "Требует внимания", "Здоров": "Здоров"}[worst]
    return worst, status_map[worst], indicator


def generate_json(md_path: Path, code: str, output_path: Path = None) -> dict:
    """Главная функция: MD → JSON."""
    md_text = md_path.read_text(encoding="utf-8")

    # Парсим секции
    s3 = parse_s3(md_text)
    s4 = parse_s4(md_text)
    s5 = parse_s5(md_text)
    s6 = parse_s6(md_text)
    s7 = parse_s7(md_text)
    s8 = parse_s8(md_text)

    # Считаем summary
    section_verdicts = {
        "s3": {"verdict": s3["verdict"], **s3["counts"]},
        "s4": {"verdict": s4["verdict"]},
        "s5": {"verdict": s5["verdict"], **s5["counts"]},
        "s6": {"verdict": s6["verdict"]},
    }
    total_critical = sum(s.get("critical", 0) for s in (s3, s5))
    total_warning = sum(s.get("warning", 0) for s in (s3, s5))
    total_info = sum(s.get("info", 0) for s in (s3, s5))
    verdict, verdict_status, indicator_text = compute_summary_verdict(section_verdicts)

    # Собираем JSON
    result = {
        "_meta": parse_meta(md_text, code),
        "summary": {
            "verdict": verdict,
            "verdict_status": verdict_status,
            "indicator_text": indicator_text,
            "section_verdicts": section_verdicts,
            "total_counts": {
                "critical": total_critical,
                "warning": total_warning,
                "info": total_info,
            },
        },
        "sections": {
            "s3": s3,
            "s4": s4,
            "s5": s5,
            "s6": s6,
            "s7": s7,
            "s8": s8,
        },
        "metadata": parse_metadata(md_text),
    }

    if output_path:
        output_path.write_text(
            json.dumps(result, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        print(f"✅ Saved: {output_path} ({output_path.stat().st_size} bytes)")

    return result


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--code", help="Код проекта (например 504-314)")
    ap.add_argument("--md", help="Путь к MD-файлу")
    ap.add_argument("--output", help="Путь к выходному JSON")
    args = ap.parse_args()

    if args.md:
        md_path = Path(args.md)
        code = args.code or re.search(r'project_([\d-]+)_report', md_path.name).group(1)
    else:
        code = args.code
        md_path = Path(f"/tmp/project_{code}_report.md")
        if not md_path.exists():
            print(f"❌ Не найден {md_path}")
            return 1

    output = Path(args.output) if args.output else Path(f"/tmp/project-json-design/examples/v{SCHEMA_VERSION}_{code}.json")
    output.parent.mkdir(parents=True, exist_ok=True)
    generate_json(md_path, code, output)
    return 0


if __name__ == "__main__":
    sys.exit(main())

