def normalize_verdict(text: str) -> str:
    """Нормализует вердикт к стандартному формату ('Болен'/'Требует внимания'/'Здоров')."""
    t = text.strip().lower()
    if "болен" in t:
        return "Болен"
    if "внимания" in t:
        return "Требует внимания"
    if "здоров" in t:
        return "Здоров"
    return "Здоров"


