    """Раздел 5: актуальность прогнозов."""
    sec = parse_section(md_text, 5)
    verdict, counts = parse_verdict(sec)
    rows = parse_md_table(sec)
    overdue = []
    for row in rows:
        if len(row) < 7:
            continue
        # MD: [#, Цвет, Статус, Код КТ, Название, План, Прогноз, Дней]
        try:
            # overdue_days может быть None, "—" или числом
            overdue_raw = row[7]
            overdue_days = None
            if overdue_raw and overdue_raw != "—":
                try:
                    overdue_days = int(overdue_raw)
                except ValueError:
                    overdue_days = None
            overdue.append({
                "code": row[3],
                "name": row[4],
                "plan": row[5] if row[5] != "—" else None,
                "forecast": row[6] if row[6] != "—" else None,
                "overdue_days": overdue_days,
                "status": row[2],
                "color": row[1],
            })
        except (IndexError, ValueError):
