def parse_attr_values(records):
    """Парсит AttrValue каждой записи, возвращает dict по source.

    Поддерживает 2 формата:
    1. Split-формат: {"_part_name": "summary", "_part_data": {verdict, ...}}
       Извлекаем _part_data, source из _part_name.
    2. Full-формат: {"_meta": ..., "summary": ..., "sections": ...}
       Сохраняем как есть, source = "_full".

    Если в записи есть "_meta" и "summary" — это full-формат.
    Иначе если есть "_part_data" — split-формат.
    """
    t0 = time.time()
    parts = {}
    for row in records:
        raw = row.get("AttrValue", "")
        if not raw or not isinstance(raw, str):
            continue
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            continue
        if not isinstance(data, dict):
            continue

        # Определяем формат
        if "_meta" in data and "summary" in data and "sections" in data:
            # Full JSON — сохраняем целиком
            parts["_full"] = data
        elif "_part_data" in data and isinstance(data["_part_data"], dict):
            # Split-формат
            source = data.get("_part_name") or row.get("AttrValueSource") or "_unknown"
            parts[source] = data["_part_data"]
        elif "_part_name" in data:
            # Split-формат без _part_data (старый формат)
            source = data["_part_name"]
            parts[source] = {k: v for k, v in data.items() if k != "_part_name"}
        else:
            # Неизвестный формат
            source = row.get("AttrValueSource") or "_unknown"
            parts[source] = data

    elapsed = time.time() - t0
    return parts, elapsed

